sheet.css:
.pk{--main:#5b8def;--border:#000;--surface:#fff;--page:#dfe5f2;--error:#ff5252;--muted:#d4d4d4;
  --gap:#fff;--r:5px;
  background:var(--page);color:var(--border);font-weight:500}
[data-theme=dark].pk,[data-theme=dark] .pk{--border:#fff;--surface:#111;--page:#1b2233;
  --muted:#3f3f46;--gap:#111;color:var(--border)}
.stage.pk{--page:#dfe5f2;background:var(--page)}
.stage[data-theme=dark]{--page:#1b2233}
.pk h3,.pk h4{font-weight:700;margin:0}

/* offsets are tokens; the hover translate is DERIVED from them so a variant
   cannot desync the pair. See modules.md -> Button. */
.pk-btn{--sx:4px;--sy:4px;
  font:500 15px/1 inherit;background:var(--main);color:#000;border:2px solid var(--border);
  border-radius:var(--r);box-shadow:var(--sx) var(--sy) 0 0 var(--border);
  padding:11px 18px;cursor:pointer;transition:transform .1s,box-shadow .1s}
.pk-btn:hover{transform:translate(var(--sx),var(--sy));box-shadow:0 0 0 0 var(--border)}
.pk-btn:active{transform:translate(calc(var(--sx) + 1px),calc(var(--sy) + 1px));
  box-shadow:0 0 0 0 var(--border)}
.pk-btn:focus-visible{outline:none;
  box-shadow:var(--sx) var(--sy) 0 0 var(--border),0 0 0 3px var(--gap),0 0 0 6px var(--border)}
.pk-btn.sec{background:var(--surface);color:var(--border)}
.pk-btn.danger{background:var(--error);color:#000}
.pk-btn[disabled]{box-shadow:none;background:var(--muted);color:#6b7280;cursor:not-allowed;transform:none}
[data-theme=dark] .pk-btn[disabled]{color:#9ca3af}
.f-hover{transform:translate(4px,4px);box-shadow:0 0 0 0 var(--border)!important}
.f-active{transform:translate(5px,5px);box-shadow:0 0 0 0 var(--border)!important}
.f-focus{box-shadow:4px 4px 0 0 var(--border),0 0 0 3px var(--gap),0 0 0 6px var(--border)!important}

.pk-card{background:var(--surface);border:2px solid var(--border);border-radius:var(--r);
  box-shadow:4px 4px 0 0 var(--border);padding:18px}
.pk-field{width:100%;font:500 15px/1.2 inherit;background:var(--surface);color:var(--border);
  border:2px solid var(--border);border-radius:var(--r);padding:10px 12px}
.pk-field:focus-visible{outline:none;box-shadow:0 0 0 3px var(--gap),0 0 0 6px var(--border)}
.pk-label{display:block;font-weight:700;margin:0 0 6px}
.pk-err{display:inline-block;margin-top:8px;background:var(--error);color:#000;
  border:2px solid var(--border);border-radius:var(--r);padding:5px 9px;font-weight:700;font-size:13px}

.pk-nav{border-bottom:2px solid var(--border);background:var(--surface);padding:12px 16px;
  display:flex;align-items:center;gap:20px;font-weight:700}
.pk-nav .sp{flex:1}
.pk-nav a{color:var(--border);text-decoration:none;font-weight:500;padding:5px 9px;
  border:2px solid transparent;border-radius:var(--r)}
.pk-nav a[aria-current]{background:var(--main);border-color:var(--border);color:#000}
.pk-nav.stuck{box-shadow:0 4px 0 0 var(--border)}

table.pk-t{width:100%;border-collapse:separate;border-spacing:0;background:var(--surface);
  border:2px solid var(--border);border-radius:var(--r);overflow:hidden}
table.pk-t th{background:var(--main);color:#000;font-weight:700;text-align:left}
table.pk-t th,table.pk-t td{border-bottom:2px solid var(--border);padding:10px 14px}
table.pk-t tr:last-child td{border-bottom:0}

.pk-scrim{background:rgba(0,0,0,.8);border-radius:var(--r);padding:40px 22px;display:flex;justify-content:center}
.pk-empty{border:2px dashed var(--border);border-radius:var(--r);background:transparent;padding:30px;text-align:center}
.pk-skel{height:14px;background:var(--muted);border:2px solid var(--border);border-radius:var(--r);margin-bottom:9px}
.swatch{border:2px solid #000;border-radius:5px;height:54px}
